IF EXISTS ( SELECT 1 FROM audit_operation_mapping target JOIN ( VALUES ('/api/catalog/tag-categories', 'POST'), ('/api/catalog/tag-categories/{id}', 'PUT'), ('/api/catalog/tag-categories/{id}', 'DELETE'), ('/api/catalog/tags', 'POST'), ('/api/catalog/tags/{id}', 'PUT'), ('/api/catalog/tags/{id}', 'DELETE'), ('/api/catalog/asset-tags', 'POST'), ('/api/catalog/asset-tags', 'DELETE'), ('/api/catalog/asset-tags/batch', 'POST'), ('/api/catalog/tags/builtin/install', 'POST'), ('/api/catalog/tag-migrations/dry-run', 'POST'), ('/api/catalog/tag-migrations/{batchId}/execute', 'POST'), ('/api/catalog/tag-migrations/{batchId}/rollback', 'POST') ) desired(url_pattern, http_method) ON target.url_pattern = desired.url_pattern AND target.http_method = desired.http_method ) THEN RAISE EXCEPTION 'Sprint-71 catalog tag audit route already exists; refusing to overwrite pre-existing data'; END IF; END $catalog_tag_audit_guard$;

